async createOrder(rawIdempotencyKey: string | undefined, rawBody: unknown): Promise<Order> {
  validateIdempotencyKey(rawIdempotencyKey);
  const input = validateCreateOrderBody(rawBody);

  return this.writeLock.run(async () => {
    const product = await this.products.findById(input.productId);
    if (!product) throw new AppError("NOT_FOUND", `product ${input.productId} not found`);

    // M-01은 이 재고 검사를 제거하거나 조건을 반전한다.
    if (input.quantity > product.stock) {
      throw new AppError(
        "INSUFFICIENT_STOCK",
        `requested ${input.quantity} but only ${product.stock} in stock`,
      );
    }

    const order: Order = {
      id: this.newId(),
      productId: input.productId,
      quantity: input.quantity,
      status: "CREATED",
    };
    await this.products.adjustStock(product.id, -input.quantity);
    await this.orders.insert(order);
    return order;
  });
}

constructor(code: ErrorCode, message: string) {
  super(message);
  this.name = "AppError";
  this.code = code;
  this.status = ERROR_STATUS[code];
}

export function validateIdempotencyKey(raw: string | undefined): string {
  if (typeof raw !== "string" || raw.length === 0) {
    throw new AppError("VALIDATION_ERROR", "Idempotency-Key header is required");
  }
  if (raw.length > IDEMPOTENCY_KEY_MAX_LENGTH) {
    throw new AppError(
      "VALIDATION_ERROR",
      `Idempotency-Key must be at most ${IDEMPOTENCY_KEY_MAX_LENGTH} characters`,
    );
  }
  return raw;
}

